CREATE TABLE IF NOT EXISTS hub_settings (id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hub_visitors (id TEXT PRIMARY KEY, seen INTEGER NOT NULL, country TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS hub_visitors_seen ON hub_visitors(seen);
CREATE TABLE IF NOT EXISTS hub_countries (country TEXT PRIMARY KEY, visits INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS hub_likes (id TEXT PRIMARY KEY, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS hub_guestbook (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, message TEXT NOT NULL, created INTEGER NOT NULL, approved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS hub_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, contact TEXT NOT NULL, message TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS hub_limits (id TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS hub_cache (id TEXT PRIMARY KEY, body TEXT NOT NULL, updated INTEGER NOT NULL);
